// Unidad (forma de la app) -> fila lista para insert/upsert en Supabase.
function unitToRow(unit) {
  const row = { id: unit.id, odometro: odometroActualDe(unit) };
  UNIT_SCALAR_FIELDS.forEach(([camel, snake]) => {
    const v = unit[camel];
    row[snake] = v === undefined || v === "" ? null : v;
  });
  UNIT_JSON_FIELDS.forEach(([camel, snake]) => {
    row[snake] = unit[camel] || [];
  });
  return row;
}

// Fila de Supabase -> unidad en la forma que espera el resto de la app.
function rowToUnit(row) {
  const unit = { id: row.id, odometro: row.odometro || 0 };
  UNIT_SCALAR_FIELDS.forEach(([camel, snake]) => {
    const v = row[snake];
    unit[camel] = v === null || v === undefined ? "" : v;
  });
  UNIT_JSON_FIELDS.forEach(([camel, snake]) => {
    unit[camel] = row[snake] || [];
  });
  return unit;
}

function Badge({ tone, children }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}

function StatusDot({ estatus }) {
  const tone = estatus === "Activo" ? "ok" : estatus === "En taller" ? "proximo" : estatus === "Fuera de servicio" ? "urgente" : "vencido";
  return <span className={`status-dot status-dot-${tone}`} />;
}

